function mdo = opf_case74ds(gen_QMIN_13, bus_VMAX_44)
%OPF_CASE74DS Multi-period DC OPF (MOST) for case74ds with scenario-driven parameter updates

define_constants;

%% load base case
casefile = 'case74ds';
mpc0 = loadcase(casefile);

%% scenario-driven parameter modifications with direction validation
% 1) Generator at bus 13: QMIN increases (i.e., becomes >= original QMIN)
idx_g13 = find(mpc0.gen(:, GEN_BUS) == 13);
assert(~isempty(idx_g13), 'No generator found at bus 13');
% if multiple gens at bus 13, apply to all to respect scenario direction
for k = 1:numel(idx_g13)
    g = idx_g13(k);
    qmin0 = mpc0.gen(g, QMIN);
    assert(gen_QMIN_13 >= qmin0, 'Parameter must increase');
end

% 2) Bus 44: VMAX increases
b44 = find(mpc0.bus(:, BUS_I) == 44);
assert(~isempty(b44) && numel(b44) == 1, 'Bus 44 not found or not unique');
vmax0_44 = mpc0.bus(b44, VMAX);
assert(bus_VMAX_44 >= vmax0_44, 'Parameter must increase');

%% apply modifications
mpc = mpc0;
for k = 1:numel(idx_g13)
    g = idx_g13(k);
    mpc.gen(g, QMIN) = gen_QMIN_13;
end
mpc.bus(b44, VMAX) = bus_VMAX_44;

%% MOST multi-period DC OPF setup (template-aligned)
% DC model
mpopt = mpoption('most.dc_model', 1, ...
                 'opf.violation', 1e-6);

% NOTE: This template expects external xGen and profile data. To keep this
% function self-contained while still implementing the multi-period MOST
% structure, we build a minimal deterministic multi-period data set with a
% flat profile (no structural scenario changes beyond the specified limits).
% Users can replace the profiles and xgd with their own datasets.

nt = 2; % placeholder number of periods for multi-period formulation

% create simple load profiles (identity scaling)
% MOST profiles are specified via md.profile entries; we keep loads constant.
profiles = struct([]);
profiles(1).type = 'mpcData';
profiles(1).table = CT_TBUS;
profiles(1).rows = (1:size(mpc.bus,1))';
profiles(1).col = PD;
profiles(1).chgtype = CT_REP;
profiles(1).values = repmat(mpc.bus(:, PD), 1, nt);

profiles(2).type = 'mpcData';
profiles(2).table = CT_TBUS;
profiles(2).rows = (1:size(mpc.bus,1))';
profiles(2).col = QD;
profiles(2).chgtype = CT_REP;
profiles(2).values = repmat(mpc.bus(:, QD), 1, nt);

% xGen data: empty (no additional flexible resources)
xgd = [];

% build MOST data model
mdi = loadmd(mpc, nt, xgd, [], [], profiles);

% run MOST
mdo = most(mdi, mpopt);

% optional: expose commonly used outputs to caller via returned mdo
% ExpectedDispatch = mdo.results.ExpectedDispatch;
% GenPrices        = mdo.results.GenPrices;

end

function results = opf_case141(bus_PD_44, bus_QD_137, branch_TAP_63_42)
%OPF_CASE141  DC-SCOPF for case141 with angle-difference penalty and scenario parameter edits.
%
% Inputs (placeholders representing post-modification values):
%   bus_PD_44          - new PD at bus 44 (must Increase)
%   bus_QD_137         - new QD at bus 137 (must Increase)
%   branch_TAP_63_42   - new TAP for branch 63->42 (must Increase)
%
% Output:
%   results - MATPOWER results struct (external indexing)

define_constants;

%% load case
mpc0 = loadcase('case141');
if isempty(mpc0)
    error('Failed to load case141');
end

%% ===== scenario-driven parameter modifications (with direction asserts) =====
% bus 44 PD increase
b44 = find(mpc0.bus(:, BUS_I) == 44, 1);
assert(~isempty(b44), 'Bus 44 not found');
PD_old_44 = mpc0.bus(b44, PD);
assert(bus_PD_44 >= PD_old_44, 'Parameter must increase');
mpc0.bus(b44, PD) = bus_PD_44;

% bus 137 QD increase
b137 = find(mpc0.bus(:, BUS_I) == 137, 1);
assert(~isempty(b137), 'Bus 137 not found');
QD_old_137 = mpc0.bus(b137, QD);
assert(bus_QD_137 >= QD_old_137, 'Parameter must increase');
mpc0.bus(b137, QD) = bus_QD_137;

% branch 63-42 TAP increase (handle either orientation by matching both ends)
br6342 = find(mpc0.branch(:, F_BUS) == 63 & mpc0.branch(:, T_BUS) == 42, 1);
assert(~isempty(br6342), 'Branch 63->42 not found');
TAP_old_63_42 = mpc0.branch(br6342, TAP);
% MATPOWER convention: TAP = 0 means 1.0; compare against effective tap
if TAP_old_63_42 == 0
    TAP_eff_old = 1.0;
else
    TAP_eff_old = TAP_old_63_42;
end
assert(branch_TAP_63_42 >= TAP_eff_old, 'Parameter must increase');
% write new tap; allow user to pass 1.0+; do not encode as 0
mpc0.branch(br6342, TAP) = branch_TAP_63_42;

%% ===== solver / model options =====
SOLVER = 'MIPS';
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', SOLVER);
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ===== build DC-SCOPF model (internal indexing) =====
mpc = ext2int(mpc0);
baseMVA = mpc.baseMVA;
bus    = mpc.bus;
branch = mpc.branch;

nb = size(bus, 1);
nl = size(branch, 1);

% DC network matrices
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

% contingency set: in-service branches with RATE_A > 0
in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0);
cont_set   = find(in_service & has_limit);
nc = length(cont_set);
if isempty(cont_set)
    error('Contingency set is empty! No in-service lines with RATE_A limits.');
end

% set up OPF model
om = opf_setup(mpc, mpopt);
nv = om.var.N;

iVa1 = om.var.idx.i1.Va;
iVaN = om.var.idx.iN.Va;

%% ===== objective modification: angle-difference quadratic penalty =====
% beta * ||E*Va||^2 = beta * Va' * (E'*E) * Va
% MATPOWER quad cost uses 0.5*x'*Q*x, so Q = 2*beta*(E'*E)
beta = 10;

% build incidence E only for in-service branches to reflect operating network
br_in = find(in_service);
nl_in = length(br_in);
f = branch(br_in, F_BUS);
t = branch(br_in, T_BUS);

E = sparse(1:nl_in, f,  1, nl_in, nb) + sparse(1:nl_in, t, -1, nl_in, nb);
Q_va = 2 * beta * (E' * E);
om = om.add_quad_cost('ang_diff_pen', Q_va, [], 0, {'Va'});

%% ===== constraint modification: N-1 branch thermal limits (DC-SCOPF) =====
rateA = branch(:, RATE_A);
constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);

nRows = 2 * nL * nc;
A = spalloc(nRows, nv, max(1, 2 * nL * nc * min(nb, 20))); % conservative sparsity guess
l = -inf(nRows, 1);
u =  inf(nRows, 1);

row = 0;
for kk = 1:nc
    k = cont_set(kk);

    lodf_col = LODF(:, k);   % nl x 1
    Bf_row_k = Bf(k, :);     % 1 x nb
    Pk       = Pfinj(k);     % scalar

    % post-contingency flow mapping
    Bf_k = Bf + lodf_col * Bf_row_k;  % nl x nb
    Pf_k = Pfinj + lodf_col * Pk;     % nl x 1

    for ii = 1:nL
        ell = constrain_lines(ii);
        limit = rateA(ell);

        aVa = Bf_k(ell, :);
        cst = Pf_k(ell);

        % f_ell^(k) <= limit
        row = row + 1;
        A(row, iVa1:iVaN) = aVa;
        u(row) = limit - cst;

        % -f_ell^(k) <= limit  <=> f_ell^(k) >= -limit
        row = row + 1;
        A(row, iVa1:iVaN) = -aVa;
        u(row) = limit + cst;
    end
end

if row ~= nRows
    error('Row count mismatch: row=%d, expected nRows=%d', row, nRows);
end

om.add_lin_constraint('N1_branch_limits', A, l, u);

%% ===== solve =====
[x, fval, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('OPF solver failed with exit flag: %d', eflag);
end

%% ===== pack results (back to external indexing) =====
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;

Va_solution = x(idx_i1.Va:idx_iN.Va);
Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

results = mpc;
results.bus(:, VA) = Va_solution * 180/pi;
results.gen(:, PG) = Pg_solution;
results.f = fval;
results.success = (eflag > 0);
results.eflag = eflag;
results.output = output;
results.lambda = lambda;

results = int2ext(results);

end

function results = opf_case22(bus_VMIN_3, bus_PD_13, bus_QD_13)
%OPF_CASE22  Level-4 DC-SCOPF for case22 with scenario parameter changes and objective modification.

define_constants;

%% ===== Load case and options =====
mpc0 = loadcase('case22');
if isempty(mpc0)
    error('Failed to load case22');
end

mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ===== Scenario-driven parameter modifications (with direction asserts) =====
% Bus 3: VMIN set to zero (disable lower voltage limit for feasibility assessment)
old_VMIN_3 = mpc0.bus(3, VMIN);
assert(bus_VMIN_3 == 0, 'Parameter must be set to zero');
mpc0.bus(3, VMIN) = bus_VMIN_3;

% Bus 13: PD increased
old_PD_13 = mpc0.bus(13, PD);
assert(bus_PD_13 >= old_PD_13, 'Parameter must increase');
mpc0.bus(13, PD) = bus_PD_13;

% Bus 13: QD increased
old_QD_13 = mpc0.bus(13, QD);
assert(bus_QD_13 >= old_QD_13, 'Parameter must increase');
mpc0.bus(13, QD) = bus_QD_13;

%% ===== Convert to internal indexing =====
mpc = ext2int(mpc0);
baseMVA = mpc.baseMVA;
bus    = mpc.bus;
branch = mpc.branch;

nb = size(bus, 1);
nl = size(branch, 1);

%% ===== Build PTDF/LODF for N-1 security constraints =====
% Bf: nl x nb, Pfinj: nl x 1
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0);
cont_set   = find(in_service & has_limit);
nc = length(cont_set);

if isempty(cont_set)
    error('Contingency set is empty! No in-service lines with RATE_A > 0.');
end

%% ===== OPF model setup =====
om = opf_setup(mpc, mpopt);

idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;

iVa1 = idx_i1.Va;
iVaN = idx_iN.Va;

nv = om.var.N;

%% ===== Add N-1 branch flow limit constraints =====
rateA = branch(:, RATE_A);
constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);

nRows = 2 * nL * nc;

% Each row touches only Va vars; allocate conservatively.
A = spalloc(nRows, nv, nRows * min(nb, 50));
l = -inf(nRows, 1);
u =  inf(nRows, 1);

row = 0;
for kk = 1:nc
    k = cont_set(kk);

    lodf_col = LODF(:, k);      % nl x 1
    Bf_row_k = Bf(k, :);        % 1 x nb
    Pk       = Pfinj(k);        % scalar

    % Post-contingency flow mapping
    Bf_k = Bf + lodf_col * Bf_row_k;   % nl x nb
    Pf_k = Pfinj + lodf_col * Pk;      % nl x 1

    for ii = 1:nL
        ell = constrain_lines(ii);
        limit = rateA(ell);

        aVa = Bf_k(ell, :);   % 1 x nb
        cst = Pf_k(ell);      % scalar

        % Upper:  aVa*Va <= limit - cst
        row = row + 1;
        A(row, iVa1:iVaN) = aVa;
        u(row) = limit - cst;

        % Lower: -aVa*Va <= limit + cst
        row = row + 1;
        A(row, iVa1:iVaN) = -aVa;
        u(row) = limit + cst;
    end
end

if row ~= nRows
    error('Row count mismatch: row=%d, expected nRows=%d', row, nRows);
end

om.add_lin_constraint('N1_branch_limits', A, l, u);

%% ===== Add quadratic reactive power generation cost: sum(c_Q .* Qg.^2) =====
% Note: This cost is added to the underlying (DC) model objective as a
% quadratic penalty on Qg variables.
ng = idx_iN.Pg - idx_i1.Pg + 1;

% If the case has Qg variables in the model indexing, apply cost; otherwise error.
if ~isfield(idx_i1, 'Qg') || ~isfield(idx_iN, 'Qg')
    error('Qg variables are not present in the OPF model; cannot add reactive power cost.');
end

nQg = idx_iN.Qg - idx_i1.Qg + 1;
if nQg ~= ng
    % This can happen for unusual cases; still proceed on Qg dimension.
end

% Use placeholder coefficients sized to number of generators if needed.
% For a fully specified implementation, user should align c_Q length to number of gens.
% Here we map/expand the template coefficients deterministically.
c_Q_template = [100; 15; 20];
if length(c_Q_template) == nQg
    c_Q = c_Q_template;
else
    c_Q = c_Q_template(mod((1:nQg)'-1, length(c_Q_template)) + 1);
end

Q_mat = sparse(1:nQg, 1:nQg, 2*c_Q, nQg, nQg);
om = om.add_quad_cost('reactive_power_generation_cost', Q_mat, [], 0, {'Qg'});

%% ===== Solve =====
[x, f, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('OPF solver failed with exit flag: %d', eflag);
end

%% ===== Pack results back into a MATPOWER results struct =====
results = mpc;

Va_solution = x(idx_i1.Va:idx_iN.Va);
Pg_solution = x(idx_i1.Pg:idx_iN.Pg);
Qg_solution = x(idx_i1.Qg:idx_iN.Qg);

results.bus(:, VA) = Va_solution * 180/pi;
results.gen(:, PG) = Pg_solution;
results.gen(:, QG) = Qg_solution;
results.f = f;
results.success = (eflag > 0);
results.eflag = eflag;
results.output = output;
results.lambda = lambda;

results = int2ext(results);

end

function out = opf_case85(gen_COST_PARAMS_C1_10, gen_COST_PARAMS_C2_8, gen_COST_PARAMS_C3_2, branch_BR_B_31_73, w_bus_ext, mu_w_MW, sigma_w_MW, eps)
%OPF_CASE85 Multi-period DCOPF (MOST) with chance-constrained line limits + scenario parameter edits
%   Inputs are placeholders representing post-modification values consistent
%   with scenario directions.

define_constants;

casefile = 'case85';
mpc0 = loadcase(casefile);

%% ---------------- scenario-driven parameter modifications ----------------
% 1) Nuclear units prioritized: decrease selected generator cost coefficients
% We interpret COST_PARAMS_Ck as polynomial cost coefficients in gencost.
% For MODEL=2 (polynomial), columns are: [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
% Here we map:
%   C2 := quadratic coefficient, C1 := linear coefficient, C0 := constant coefficient.

mpc = mpc0;

% helper to find generator row by GEN_BUS (first match)
find_gen_by_bus = @(busno) find(mpc.gen(:, GEN_BUS) == busno, 1, 'first');

% --- bus 10: decrease linear term (C1)
gi10 = find_gen_by_bus(10);
if isempty(gi10), error('No generator found at bus 10.'); end
if size(mpc.gencost, 1) < gi10, error('gencost rows do not align with gen rows.'); end
if mpc.gencost(gi10, MODEL) ~= 2
    error('This template expects polynomial gencost (MODEL=2) for generator at bus 10.');
end
ncost10 = mpc.gencost(gi10, NCOST);
assert(ncost10 >= 2, 'Generator at bus 10 must have at least 2 cost coefficients to modify C1.');
% column index of linear coefficient in polynomial form
col_c1_10 = 4 + (ncost10 - 2);
old_c1_10 = mpc.gencost(gi10, col_c1_10);
new_c1_10 = gen_COST_PARAMS_C1_10;
assert(new_c1_10 <= old_c1_10, 'Parameter must decrease');
mpc.gencost(gi10, col_c1_10) = new_c1_10;

% --- bus 8: decrease quadratic term (C2)
gi8 = find_gen_by_bus(8);
if isempty(gi8), error('No generator found at bus 8.'); end
if mpc.gencost(gi8, MODEL) ~= 2
    error('This template expects polynomial gencost (MODEL=2) for generator at bus 8.');
end
ncost8 = mpc.gencost(gi8, NCOST);
assert(ncost8 >= 3, 'Generator at bus 8 must have at least 3 cost coefficients to modify C2.');
col_c2_8 = 4 + (ncost8 - 3);
old_c2_8 = mpc.gencost(gi8, col_c2_8);
new_c2_8 = gen_COST_PARAMS_C2_8;
assert(new_c2_8 <= old_c2_8, 'Parameter must decrease');
mpc.gencost(gi8, col_c2_8) = new_c2_8;

% --- bus 2: decrease constant term (C0)
gi2 = find_gen_by_bus(2);
if isempty(gi2), error('No generator found at bus 2.'); end
if mpc.gencost(gi2, MODEL) ~= 2
    error('This template expects polynomial gencost (MODEL=2) for generator at bus 2.');
end
ncost2 = mpc.gencost(gi2, NCOST);
assert(ncost2 >= 1, 'Generator at bus 2 must have at least 1 cost coefficient to modify C0.');
col_c0_2 = 4 + (ncost2 - 1);
old_c0_2 = mpc.gencost(gi2, col_c0_2);
new_c0_2 = gen_COST_PARAMS_C3_2;
assert(new_c0_2 <= old_c0_2, 'Parameter must decrease');
mpc.gencost(gi2, col_c0_2) = new_c0_2;

% 2) Emergency simplification: set line charging susceptance BR_B to zero on branch 31-73
% Find the (first) matching branch in either direction
br_idx = find(mpc.branch(:, F_BUS) == 31 & mpc.branch(:, T_BUS) == 73, 1, 'first');
if isempty(br_idx)
    br_idx = find(mpc.branch(:, F_BUS) == 73 & mpc.branch(:, T_BUS) == 31, 1, 'first');
end
if isempty(br_idx), error('Branch 31-73 not found in case85.'); end
old_br_b = mpc.branch(br_idx, BR_B);
new_br_b = branch_BR_B_31_73;
assert(new_br_b == 0, 'Parameter must be set to zero');
mpc.branch(br_idx, BR_B) = new_br_b;

%% ---------------- multi-period DCOPF (MOST) base setup ----------------
% DC model for MOST
mpopt = mpoption('most.dc_model', 1, ...
                'model', 'DC', ...
                'opf.dc.solver', 'MIPS', ...
                'opf.violation', 1e-7, ...
                'verbose', 1, ...
                'out.all', 0);

% Create a trivial flat load profile over nt periods if no external profile is provided.
% MOST requires profiles; here we keep it self-contained with a constant profile.
if nargin < 8 || isempty(eps)
    eps = 0.05;
end
if nargin < 7 || isempty(sigma_w_MW)
    sigma_w_MW = 0;
end
if nargin < 6 || isempty(mu_w_MW)
    mu_w_MW = 0;
end
if nargin < 5 || isempty(w_bus_ext)
    w_bus_ext = mpc.bus(1, BUS_I); % default to first bus
end

% Choose nt=1 by default; users can edit here if they want multi-period >1.
nt = 1;

% Build MOST profiles: constant multipliers on PD (load)
% profile struct format: see MOST documentation; this is a minimal compatible form.
profiles = struct([]);
profiles(1).type      = 'mpcData';
profiles(1).table     = CT_TBUS;
profiles(1).rows      = (1:size(mpc.bus,1))';
profiles(1).col       = PD;
profiles(1).chgtype   = CT_REL;      % relative multiplier
profiles(1).values    = ones(nt, size(mpc.bus,1));

% xGenData empty (no unit commitment features used)
xgd = [];
mdi = loadmd(mpc, nt, xgd, [], [], profiles);

% Solve with MOST (expected dispatch)
mdo = most(mdi, mpopt);

%% ---------------- chance constraints on line limits (single-source) ----------------
% Add chance constraints to each period by re-solving a DCOPF with OM and the
% same case snapshot used by MOST at that period. For nt=1, we use the base snapshot.
% This keeps the implementation aligned with the provided chance-constraint template.

% chance level and z-value
z = norminv_approx(1 - eps/2);

% Ensure RATE_A limits exist and positive (as in the template)
rateA = mpc.branch(:, RATE_A);
if all(rateA == 0)
    mpc.branch(:, RATE_A) = 250;
else
    mpc.branch(rateA == 0, RATE_A) = 1e4;
end

% Embed mean stochastic injection as negative load at w_bus_ext
bus_idx_ext = find(mpc.bus(:, BUS_I) == w_bus_ext, 1, 'first');
if isempty(bus_idx_ext), error('Wind/stochastic injection bus not found.'); end
mpc_mean = mpc;
mpc_mean.bus(bus_idx_ext, PD) = mpc_mean.bus(bus_idx_ext, PD) - mu_w_MW;

% convert to internal indexing
mpc_i   = ext2int(mpc_mean);
baseMVA = mpc_i.baseMVA;
bus     = mpc_i.bus;
branch  = mpc_i.branch;
gen     = mpc_i.gen;

nb = size(bus, 1);
nl = size(branch, 1);
ng = size(gen, 1);

% PTDF and mapping
PTDF = makePTDF(baseMVA, bus, branch);
Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);
Pd = bus(:, PD) / baseMVA;

% internal index of stochastic bus
tmp = ext2int(mpc0);
w_bus_int = find(tmp.bus(:, BUS_I) == w_bus_ext, 1);
if isempty(w_bus_int), error('Wind bus internal mapping failed.'); end

sigma_w_pu = sigma_w_MW / baseMVA;
ptdf_w  = PTDF(:, w_bus_int);
sigma_f = abs(ptdf_w) * sigma_w_pu;

% Build DC OPF model
om = opf_setup(mpc_i, mpopt);
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch.');
end
nv = om.var.N;

Fmax = branch(:, RATE_A) / baseMVA;

Arows = [];
u = [];
lb = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    a_pg  = PTDF(ell,:) * Cg;
    const = PTDF(ell,:) * (-Pd);
    margin  = Fmax(ell) - z * sigma_f(ell);
    rhs_pos = margin - const;
    rhs_neg = margin + const;

    Arows(end+1,:) = a_pg; %#ok<AGROW>
    lb(end+1,1)    = -Inf; %#ok<AGROW>
    u(end+1,1)     = rhs_pos; %#ok<AGROW>

    Arows(end+1,:) = -a_pg; %#ok<AGROW>
    lb(end+1,1)    = -Inf; %#ok<AGROW>
    u(end+1,1)     = rhs_neg; %#ok<AGROW>
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A,1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('CHANCE_LINE_LIMITS', Afull, lb, u);
end

% solve chance-constrained DCOPF snapshot
try
    [res_i, success, raw] = opf_execute(om, mpopt); %#ok<ASGLU>
catch
    [res_i, success, raw] = opf_execute(om, mpc_i, mpopt); %#ok<ASGLU>
end
res = int2ext(res_i, mpc_mean);

if ~success
    error('Chance-constrained DCOPF failed.');
end

% outputs
out = struct();
out.mdo = mdo;
out.cc_res = res;
out.cc_success = success;
out.cc_objective = res.f;
out.eps = eps;
out.z = z;
out.w_bus_ext = w_bus_ext;
out.mu_w_MW = mu_w_MW;
out.sigma_w_MW = sigma_w_MW;

end

function z = norminv_approx(p)
% Compute z = Phi^{-1}(p) without requiring Statistics Toolbox.
z = -sqrt(2) * erfcinv(2*p);
end

function mdo = opf_case118(branch_TAP_9_116, gen_PMIN_2)
%OPF_CASE118  Multi-period DC SCUC-style MOST run for case118 with scenario-driven parameter modifications.
%   mdo = opf_case118(branch_TAP_9_116, gen_PMIN_2)
%
% Inputs (placeholders representing post-modification values):
%   branch_TAP_9_116 : new TAP for branch 9-116 (must Increase vs original)
%   gen_PMIN_2       : new PMIN for generator at bus 2 (must Decrease vs original)

define_constants;

%% 1) Load case
mpc = loadcase('case118');

%% 2) Scenario-driven parameter modifications with direction asserts
% --- Branch TAP increase on corridor 9 -> 116
fbus = 9; tbus = 116;
br = find(mpc.branch(:, F_BUS) == fbus & mpc.branch(:, T_BUS) == tbus);
if isempty(br)
    % some cases store in opposite direction
    br = find(mpc.branch(:, F_BUS) == tbus & mpc.branch(:, T_BUS) == fbus);
end
assert(~isempty(br), 'Branch between bus 9 and bus 116 not found in case118.');
assert(numel(br) == 1, 'Multiple branches found between bus 9 and bus 116; specify unique corridor.');
orig_tap = mpc.branch(br, TAP);
if orig_tap == 0
    orig_tap = 1; % MATPOWER convention: 0 means 1.0 p.u. tap
end
assert(branch_TAP_9_116 >= orig_tap, 'Parameter must increase');
mpc.branch(br, TAP) = branch_TAP_9_116;

% --- Generator PMIN decrease at bus 2
g = find(mpc.gen(:, GEN_BUS) == 2);
assert(~isempty(g), 'No generator found at bus 2 in case118.');
if numel(g) > 1
    % apply to all gens at bus 2 consistently
    for k = 1:numel(g)
        orig_pmin = mpc.gen(g(k), PMIN);
        assert(gen_PMIN_2 <= orig_pmin, 'Parameter must decrease');
        mpc.gen(g(k), PMIN) = gen_PMIN_2;
    end
else
    orig_pmin = mpc.gen(g, PMIN);
    assert(gen_PMIN_2 <= orig_pmin, 'Parameter must decrease');
    mpc.gen(g, PMIN) = gen_PMIN_2;
end

%% 3) MOST / multi-period SCUC template structure (DC model)
verbose = 1;
mpopt = mpoption('verbose', verbose);
mpopt = mpoption(mpopt, 'out.gen', 1);
mpopt = mpoption(mpopt, 'model', 'DC');

% solver requirements
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'most.solver', 'MIPS');
mpopt = mpoption(mpopt, 'most.price_stage_warn_tol', 1e-5);
mpopt = mpoption(mpopt, 'most.dc_model', 1);    % use DC network model

if have_feature('intlinprog')
    mpopt = mpoption(mpopt, 'linprog.Algorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.RootLPAlgorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.TolCon', 1e-9);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapAbs', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapRel', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolInteger', 1e-6);
end

%% 4) Load extended generator data for UC
% Note: using example xgd bundle; user can swap with a case118-consistent xgendata file.
xgd = loadxgendata('ex_xgd_uc', mpc);

%% 5) Add wind + profiles (example profile files)
[iwind, mpc, xgd] = addwind('ex_wind_uc', mpc, xgd);
windprofile = struct( ...
    'type', 'mpcData', ...
    'table', CT_TGEN, ...
    'rows', 1, ...
    'col', PMAX, ...
    'chgtype', CT_REL, ...
    'values', [] );
wp = ex_wind_profile;
windprofile.values(:, :, 1) = mean(wp.values, 2);
profiles = getprofiles(windprofile, iwind);
profiles = getprofiles('ex_load_profile', profiles);
nt = size(profiles(1).values, 1);

%% 6) Example commitment-related edits (template-consistent)
% Keep indices safe for case118 by checking sizes.
ng = size(mpc.gen, 1);
if size(mpc.gencost, 1) >= 3
    if size(mpc.gencost, 2) >= SHUTDOWN
        mpc.gencost(2, [STARTUP SHUTDOWN]) = [300 300];
        mpc.gencost(3, [STARTUP SHUTDOWN]) = [2000 500];
    end
end
if isfield(xgd, 'MinUp') && numel(xgd.MinUp) >= 2
    xgd.MinUp(2) = 2;
end
if isfield(xgd, 'MinDown') && numel(xgd.MinDown) >= 3
    xgd.MinDown(3) = 2;
end
if isfield(xgd, 'PositiveLoadFollowReserveQuantity') && numel(xgd.PositiveLoadFollowReserveQuantity) >= 3
    xgd.PositiveLoadFollowReserveQuantity(3) = 120;
end
if isfield(xgd, 'PositiveLoadFollowReservePrice') && numel(xgd.PositiveLoadFollowReservePrice) >= 3
    xgd.PositiveLoadFollowReservePrice(3) = 10;
end
if isfield(xgd, 'NegativeLoadFollowReservePrice') && numel(xgd.NegativeLoadFollowReservePrice) >= 3
    xgd.NegativeLoadFollowReservePrice(3) = 10;
end

%% 7) Add storage (cyclic SOC)
mpopt = mpoption(mpopt, 'most.storage.cyclic', 1);
[iess, mpc, xgd, sd] = addstorage('ex_storage', mpc, xgd);

%% 8) Build multi-period data model and solve with MOST
mdi = loadmd(mpc, nt, xgd, sd, [], profiles);
mdo = most(mdi, mpopt);

if verbose
    most_summary(mdo);
end

end
